      // 异号（US: Unlike Sign）- 品红色，实心菱形
      hP_US_vsR->SetMarkerStyle(22);
      hP_US_vsR->SetMarkerColor(kMagenta);
      hP_US_vsR->SetMarkerSize(1.5);  // 添加标记大小
