    c->SaveAs(Form("/home/suyoupeng/Downloads/lambdaspincorefile/Analysiscode/Sourav_code/RootFile_UncertaintyFromPtEtaPhiValue/compare_hP_US_SS_%s.pdf", PtEtaPhi.Data()));

    delete c;
